args.command:
cd /bench/repo && cat > /tmp/ent.pl <<'EOF'
use strict; use warnings;
my $root="/bench/repo";
my @types = qw(User Memo Attachment Reaction Inbox IdentityProvider UserSetting UserIdentity MemoRelation MemoShare InstanceSetting);
my @files = grep { !m{/\.git/|/web/|/node_modules/} } split /\n/, `find $root -name '*.go' -type f`;
for my $t (@types) {
  my (%allpkg,%prodpkg,%allpkg_nt);
  my $sites=0;
  for my $f (@files) {
    my ($d)=$f=~m{^(.*)/[^/]+$};
    next if $d =~ m{^\Q$root\E/store};      # exclude data layer tree
    next if $d =~ m{^\Q$root\E/proto};       # generated protos
    open my $fh,'<',$f or next; local $/; my $txt=<$fh>; close $fh;
    my $h = () = $txt =~ /(?<![\w.])store\.\Q$t\E\b(?!\w)/g;
    next unless $h>0;
    my $rel=$d; $rel=~s{^\Q$root\E/}{};
    $allpkg{$rel}+=$h; $sites+=$h;
    $prodpkg{$rel}+=$h if $f!~/_test\.go$/;
  }
  printf("%-18s pkgs=%-3d prodpkgs=%-3d refs=%-4d  %s\n", $t, scalar(keys %allpkg), scalar(keys %prodpkg), $sites, join(", ", sort keys %allpkg));
}
EOF
perl /tmp/ent.pl
